int x = 0;                       /* a global */
void *bump(void *arg) { x = 1; return NULL; }

int main(void) {
    if (fork() == 0) {           /* child process */
        x = 1;
        exit(0);
    }
    wait(NULL);
    printf("after fork: x=%d\n", x);
    pthread_t t;
    pthread_create(&t, NULL, bump, NULL);
    pthread_join(t, NULL);
    printf("after thread: x=%d\n", x);
    return 0;
}

